import pandas as pd
import requests
from datetime import datetime, timezone

now = datetime.now(timezone.utc)
now_epoch = int(now.timestamp())

EXPECTED_COLUMNS = [
    'storm_id', 'storm_name', 'classification', 'intensity_kts',
    'pressure_mb', 'latitude', 'longitude', 'movement_dir',
    'movement_speed_kts', 'last_update_epoch', 'basin',
    'severity_tier', 'economic_thesis', 'advisory_url', '_epoch',
]

def classify_basin(lat, lon):
    if lat is None or lon is None:
        return 'UNKNOWN'
    if lon >= -100.0 and lon <= 0.0 and lat >= 0.0 and lat <= 45.0:
        return 'NORTH_ATLANTIC'
    if lon >= -180.0 and lon <= -80.0 and lat >= 0.0 and lat <= 35.0:
        return 'EAST_PACIFIC'
    if lon >= 100.0 and lon <= 180.0 and lat >= 0.0 and lat <= 45.0:
        return 'WEST_PACIFIC'
    if lon >= 30.0 and lon <= 115.0 and lat >= -30.0 and lat <= 30.0:
        return 'INDIAN_OCEAN'
    return 'OTHER'

def basin_thesis(basin):
    if basin == 'NORTH_ATLANTIC':
        return 'Gulf refinery / oil disruption (USO, XLE, refiners VLO/MPC), FL/NC insurers, reinsurance (RE, TRV)'
    if basin == 'EAST_PACIFIC':
        return 'Mexico tourism / manufacturing (EWW), West-coast shipping lanes'
    if basin == 'WEST_PACIFIC':
        return 'Japan/Taiwan/Philippines supply chain (TSM, Sony, EWT, EPHE, EWJ)'
    if basin == 'INDIAN_OCEAN':
        return 'India/Bangladesh/Madagascar emerging markets (INDA); textile/pharma supply'
    return 'Global reinsurance exposure (KIE ETF, TRV, RE)'

def classify_severity(classification, intensity):
    cls_upper = (classification or '').upper()
    if cls_upper == 'HU' or cls_upper == 'HURRICANE' or cls_upper == 'TY' or cls_upper == 'TYPHOON':
        if intensity is not None and intensity >= 111.0:
            return 'MAJOR'
        return 'HIGH'
    if cls_upper == 'TS' or cls_upper == 'TROPICAL_STORM':
        return 'MODERATE'
    if cls_upper == 'TD' or cls_upper == 'TROPICAL_DEPRESSION':
        return 'LOW'
    return 'LOW'

def parse_iso(val):
    if not val:
        return 0
    try:
        dt = datetime.fromisoformat(str(val).replace('Z', '+00:00'))
        return int(dt.timestamp())
    except Exception:
        return 0

storms = []
try:
    resp = requests.get(
        'https://www.nhc.noaa.gov/CurrentStorms.json',
        headers={'User-Agent': 'speakesquery (macro-brief) ingestion'},
        timeout=30,
    )
    resp.raise_for_status()
    payload = resp.json() or {}
    raw = payload.get('activeStorms', []) or []
    if isinstance(raw, list):
        storms = raw
except Exception:
    storms = []

rows = []
for si in range(len(storms)):
    storm = storms[si]
    if not isinstance(storm, dict):
        continue
    lat_raw = storm.get('latitudeNumeric')
    lon_raw = storm.get('longitudeNumeric')
    lat = None
    if lat_raw is not None:
        try:
            lat = float(lat_raw)
        except Exception:
            lat = None
    lon = None
    if lon_raw is not None:
        try:
            lon = float(lon_raw)
        except Exception:
            lon = None
    intensity_raw = storm.get('intensity')
    intensity = None
    if intensity_raw is not None:
        try:
            intensity = float(intensity_raw)
        except Exception:
            intensity = None
    pressure_raw = storm.get('pressure')
    pressure = None
    if pressure_raw is not None:
        try:
            pressure = float(pressure_raw)
        except Exception:
            pressure = None
    mvt_speed_raw = storm.get('movementSpeed')
    mvt_speed = None
    if mvt_speed_raw is not None:
        try:
            mvt_speed = float(mvt_speed_raw)
        except Exception:
            mvt_speed = None
    basin = classify_basin(lat, lon)
    classification = str(storm.get('classification', '') or '')
    severity = classify_severity(classification, intensity)
    thesis = basin_thesis(basin)
    pub_adv = storm.get('publicAdvisory')
    adv_url = ''
    if isinstance(pub_adv, dict):
        adv_url = str(pub_adv.get('url', '') or '')
    rows.append({
        'storm_id': str(storm.get('id', '') or ''),
        'storm_name': str(storm.get('name', '') or ''),
        'classification': classification,
        'intensity_kts': intensity,
        'pressure_mb': pressure,
        'latitude': lat,
        'longitude': lon,
        'movement_dir': str(storm.get('movementDir', '') or ''),
        'movement_speed_kts': mvt_speed,
        'last_update_epoch': parse_iso(storm.get('lastUpdate')),
        'basin': basin,
        'severity_tier': severity,
        'economic_thesis': thesis,
        'advisory_url': adv_url,
        '_epoch': now_epoch,
    })

if rows:
    df = pd.DataFrame(rows, columns=EXPECTED_COLUMNS)
else:
    df = pd.DataFrame(columns=EXPECTED_COLUMNS)

GENERATE_RESULTS(df)
